const neutralRoles: Record<NeutralKey, Pick<ShowroomColorPalette, "canvas" | "surface" | "layer" | "text" | "textMuted" | "inverse" | "onInverse" | "border">> = {
  cool: { canvas: "#ffffff", surface: "#f3f6f8", layer: "#e4eaf0", text: "#17212b", textMuted: "#596572", inverse: "#111820", onInverse: "#ffffff", border: "#c7d0d8" },
  paper: { canvas: "#ffffff", surface: "#f6f5f2", layer: "#e9e6df", text: "#211f1c", textMuted: "#67625b", inverse: "#171614", onInverse: "#ffffff", border: "#d2cec5" },
  fresh: { canvas: "#ffffff", surface: "#f2f6f4", layer: "#e1eae5", text: "#17241e", textMuted: "#5b6961", inverse: "#111a16", onInverse: "#ffffff", border: "#c8d3cd" },
};

function palette(raw: RawClient): ShowroomColorPalette {
  const [primary, primarySoft, secondary, secondarySoft] = raw.colors;
  return {
    ...neutralRoles[raw.neutral],
    primary,
    primarySoft,
    secondary,
    secondarySoft,
    onSecondary: "#ffffff",
    strong: secondary,
    onStrong: "#ffffff",
  };
}

