function slug(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function foundationReason(style: StyleKey) {
  const profile = styleProfiles[style];
  return `${profile.tokenPack} supplies the typography, spacing, geometry, and media behavior because the brief fits ${style.replace("_", " ")} content anatomy; the palette is independently authored from the brand direction.`;
}

export const SCALE_DEMO_BUSINESSES: readonly ScaleDemoBusiness[] = clientGroups.flatMap(
  ({ industryKey, clients }, groupIndex) => clients.map((raw, index) => {
    const handle = `demo-${slug(raw.name)}`;
    const location = locations[locationPlans[industryKey][index]];
    const customPalette = palette(raw);
    const profile: SeedShowroomBrief["profile"] = {
      ...styleProfiles[raw.style],
      customPalette,
    };
    const description = `${raw.tagline} This fictional ${raw.name} showroom is designed for ${raw.customer}.`;
    return {
      handle,
      name: raw.name,
      tagline: raw.tagline,
      description,
      heroTitle: raw.heroTitle,
      heroSubtitle: raw.heroSubtitle,
      industryKey,
      logoPath: `/uploads/seed/portfolio/${handle}/logo.svg`,
      heroPath: `/uploads/seed/portfolio/${handle}/hero.webp`,
      boothPath: `/landing/showroom-booths/${handle}.svg`,
      profile: {
        ...location,
        industryKeys: [industryKey],
        latitude: location.latitude + groupIndex * 0.0004 + index * 0.0001,
        longitude: location.longitude + groupIndex * 0.0004 + index * 0.0001,
      },
      brief: {
        objective: raw.customerRequest,
        template: `${raw.visualThesis} Preserve the canonical story, process, offering, and inquiry journey.`,
        profile,
        story: {
          kicker: "Inside the work",
          title: raw.visualThesis,
          quote: raw.tagline,
        },
        process: {
          title: `How ${raw.name} takes the work from question to handoff`,
          body: "The fictional process is provisional demonstration copy and is reviewed with a real customer before use.",
          items: [...raw.process],
        },
        cta: {
          title: `Ask ${raw.name} about the closest fit.`,
          body: "Add an offering and share the use, preferred format, timing, and optional quantity in one direct inquiry.",
        },
      },
      creative: {
        customer: raw.customer,
        customerRequest: raw.customerRequest,
        paletteRequest: raw.paletteRequest,
        paletteAdvice: raw.paletteAdvice,
        logoConcept: raw.logoConcept,
        visualThesis: raw.visualThesis,
        foundationReason: foundationReason(raw.style),
      },
      offerings: raw.offerings.map(([name, category, kind, offeringDescription], offeringIndex) => ({
        name,
        category,
        kind,
        description: offeringDescription,
        imagePath: `/uploads/seed/portfolio/${handle}/product-${offeringIndex + 1}.webp`,
      })),
    } satisfies ScaleDemoBusiness;
  }),
);

export function scaleDemoBusiness(handle: string) {
  return SCALE_DEMO_BUSINESSES.find((business) => business.handle === handle);
}
